+type RetryPolicy struct { Attempts int; BaseDelay, MaxDelay time.Duration }
+var DefaultReplyRetryPolicy = RetryPolicy{Attempts: 4, BaseDelay: 500*time.Millisecond, MaxDelay: 4*time.Second}
+
+func isDeterministicProduceErr(err error) bool {
+	return errors.Is(err, ErrMessageValidationFailed) || IsMessageTooLarge(err) || errors.Is(err, context.Canceled)
+}
+
+func (p RetryPolicy) retryDelay(attempt int) time.Duration {
+	delay := p.BaseDelay << (attempt - 1)
+	if p.MaxDelay > 0 && delay > p.MaxDelay { delay = p.MaxDelay }
+	// jitter WITHIN [delay/2, delay]: the obvious rand.Int63n(delay)+delay/2
+	// spans [delay/2, 1.5*delay) and BREAKS the cap - a test caught that here
+	half := int64(delay) / 2
+	return time.Duration(half + rand.Int63n(int64(delay)-half+1))
+}
+
+func retrySend(ctx, logger, policy, topicLabel, send func() error) error {
+	for attempt := 1; attempt <= attempts; attempt++ {
+		err = send()
+		if err == nil { if attempt > 1 { ...Warn + KafkaProduceRetryRecoveries.Inc() }; return nil }
+		if isDeterministicProduceErr(err) { return err }   // stop, do not burn the budget
+		...jittered sleep, or ctx.Done() -> return err (the PRODUCE error, not the ctx one)
+	}
+	return err   // last attempt's error, VERBATIM
+}
